let benchPopupHiddenFor=null;
document.addEventListener('pointerdown',e=>{const target=e.target;if(!(target instanceof Element))return;if(target.closest('[data-app],[data-reagent-vessel]')){benchPopupHiddenFor=null;return;}const popup=document.querySelector('.bench-apparatus-popup');if(!popup||target.closest('.bench-apparatus-popup'))return;benchPopupHiddenFor=selectedApp;popup.remove();},true);
function benchVesselLabel(a){const label=equipment.find(x=>x[0]===a.type)?.[1]||a.type,same=apparatus.filter(x=>x.type===a.type);return same.length>1?`${label} ${same.findIndex(x=>x.id===a.id)+1}`:label;}
function benchPopupContents(a){return (a.contents||[]).map(c=>`<div class="apparatus-content-row"><b>${esc(c.reagent)}</b><span>${Number(c.mass)>0?Number(c.mass).toFixed(3)+' g':Number(c.volume||0).toFixed(2)+' mL'}</span></div>`).join('');}
function benchSimplePopup(){const a=selectedEquipment();if(!a||benchPopupHiddenFor===a.id)return '';if(typeof transferToolPopup==='function'){const tool=transferToolPopup(a);if(tool!==null)return tool;}const d=equipment.find(x=>x[0]===a.type),hold=acceptsLiquid(a.type)||acceptsSolid(a.type),contents=hold||a.type==='separatoryFunnel',r=reagents[apparatusPopupReagent=validPopupReagentIndex(a.type,apparatusPopupReagent)],solid=r?.[2]==='potassiumMetal',style=apparatusPopupPosition?(apparatusPopupPosition=clampPopupPosition(apparatusPopupPosition),`left:${apparatusPopupPosition.left}px;top:${apparatusPopupPosition.top}px`):`left:${(a.x||50)>52?'8px':'auto'};right:${(a.x||50)>52?'auto':'8px'}`,source=pourSelection&&apparatus.find(x=>x.id===pourSelection),target=pourTargetSelection&&apparatus.find(x=>x.id===pourTargetSelection);return `<section class="bench-apparatus-popup simple-apparatus-popup ${apparatusPopupPosition?'is-moved':'is-default'}" role="dialog" aria-label="Selected apparatus contents" style="${style}"><header class="apparatus-popup-head popup-drag-handle"><span><b>${esc(benchVesselLabel(a))}</b><small>${contents?(a.volume||0).toFixed(1)+' mL'+(d?.[3]?' / '+d[3]+' mL':''):'Selected apparatus'}</small></span><button type="button" data-apparatus-dismiss aria-label="Close apparatus panel">×</button></header><div class="apparatus-popup-content">${contents?`<div class="popup-contents-heading"><b>In this vessel</b>${a.contents?.length>1?'<button type="button" class="btn soft small" data-mix-contents>Mix</button>':''}</div><div class="popup-scroll-layout"><div id="popupContentsList" tabindex="0" aria-label="Reagents in selected vessel">${benchPopupContents(a)||'<p class="muted">Empty vessel</p>'}</div><div class="popup-scroll-buttons"><button type="button" data-popup-scroll="-1" aria-label="Scroll contents up">▲</button><button type="button" data-popup-scroll="1" aria-label="Scroll contents down">▼</button></div></div>`:a.gas?`<p>Gas: ${esc(gasName(a.gas))}</p>`:''}${transformControlsHtml()}${typeof transferBenchSolidControls==='function'?transferBenchSolidControls(a):''}${typeof transferPreparationControls==='function'?transferPreparationControls(a):''}${typeof benchSampleExportControls==='function'?benchSampleExportControls(a):''}${hold&&a.type!=='separatoryFunnel'?`<div class="simple-popup-add"><label for="apparatusPopupReagent">Add reagent</label><div class="popup-reagent-picker"><select id="apparatusPopupReagent" aria-label="Choose a reagent">${apparatusReagentOptions(a.type,apparatusPopupReagent)}</select><button type="button" data-popup-reagent-step="-1" aria-label="Previous reagent">▲</button><button type="button" data-popup-reagent-step="1" aria-label="Next reagent">▼</button></div><div class="popup-dose-fields">${benchConcentrationField('popupConcentration')}<div class="field"><label id="apparatusPopupAmountLabel" for="apparatusPopupAmount">${solid?'MASS (g)':'VOLUME (mL)'}</label><input id="apparatusPopupAmount" type="number" min="${solid?'0.01':'0.1'}" step="${solid?'0.01':'0.5'}" value="${solid?'0.05':'5'}"></div></div><button type="button" class="btn soft small" data-popup-add>＋ Add to vessel</button></div>`:''}${source?`<div class="pour-mode-message">${target?'Receiver: '+esc(benchVesselLabel(target)):'Choose a receiving vessel.'}<button type="button" data-popup-cancel-pour>Cancel pour</button></div>${target?`<div class="pour-mode-controls"><input id="pourModeAmount" aria-label="Amount to pour" type="number" min="0.001" step="any" value="${source.volume||source.contents?.reduce((s,c)=>s+(Number(c.mass)||0),0)||0}"><button type="button" class="btn small" data-popup-pour>Pour</button></div>`:''}`:''}${a.type==='separatoryFunnel'?separatoryControlsHtml(a,analyzeVessel(a).phaseInfo):''}${a.type==='splint'?splintPopupHtml():''}</div></section>`;}
